package br.com.sistemacardapio.pedido;
import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import br.com.sistemacardapio.empresa.*;import br.com.sistemacardapio.tenant.TenantContext;
@Service public class AnalyticsService{private final JdbcTemplate jdbc;private final EmpresaRepository empresas;private final TenantContext tenant;public AnalyticsService(JdbcTemplate j,EmpresaRepository e,TenantContext t){jdbc=j;empresas=e;tenant=t;}@Transactional public void registrar(String slug,Evento r){Empresa e=empresas.findBySlugAndAtivaTrue(slug).orElseThrow(()->new IllegalStateException("Empresa não encontrada"));if(!Set.of("CARDAPIO_VISUALIZADO","PRODUTO_VISUALIZADO","ADICIONADO_CARRINHO","CHECKOUT_INICIADO").contains(r.tipo()))throw new IllegalStateException("Evento inválido");UUID produto=r.produtoId();if(produto!=null&&!Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from produto where id=? and empresa_id=?)",Boolean.class,produto,e.getId())))produto=null;jdbc.update("insert into analytics_evento(id,empresa_id,produto_id,tipo,sessao) values(gen_random_uuid(),?,?,?,?)",e.getId(),produto,r.tipo(),r.sessao());}@Transactional(readOnly=true)public Map<String,Object> resumo(){UUID e=tenant.empresaIdObrigatoria();Map<String,Object> r=new LinkedHashMap<>();r.put("funil",jdbc.queryForList("select tipo,count(*) quantidade from analytics_evento where empresa_id=? and criado_em>=now()-interval '30 days' group by tipo",e));r.put("produtos",jdbc.queryForList("select p.nome,count(*) visualizacoes from analytics_evento a join produto p on p.id=a.produto_id where a.empresa_id=? and a.tipo='PRODUTO_VISUALIZADO' and a.criado_em>=now()-interval '30 days' group by p.id,p.nome order by visualizacoes desc limit 10",e));r.put("vendas",jdbc.queryForMap("select count(*) pedidos,coalesce(sum(total),0) faturamento,coalesce(avg(total),0) ticket_medio from pedido where empresa_id=? and criado_em>=now()-interval '30 days' and status<>'CANCELADO'",e));return r;}public record Evento(String tipo,UUID produtoId,String sessao){}
}
